import {Renderer} from './renderer.js';
import {BASE,PRESETS,MOODS,META,GROUPS,preset,randomize} from './model.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={undo:'M3 9h10a7 7 0 0 1 0 14M3 9l5-5M3 9l5 5',redo:'M21 9H11a7 7 0 0 0 0 14M21 9l-5-5M21 9l-5 5',download:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5',reset:'M3 11a9 9 0 1 1 2 7M3 4v7h7',frame:'M5 3H3v5m16-5h2v5M3 16v5h5m13-5v5h-5',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',orbit:'M12 3a9 9 0 1 0 9 9M3 12h18M12 3c-5 5-5 13 0 18 4-4 5-10 2-15M18 3h3v3',move:'M12 3v18M3 12h18M9 6l3-3 3 3M9 18l3 3 3-3M6 9l-3 3 3 3m12-6 3 3-3 3',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',focus:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',play:'m9 5 11 7-11 7Z',pause:'M8 5v14M16 5v14',sliders:'M4 5h6m4 0h6M4 12h11m4 0h1M4 19h1m4 0h11M10 2v6m5 1v6M5 16v6',shuffle:'M3 6h3c5 0 7 12 12 12h3m-4-4 4 4-4 4M3 18h3c2 0 3-2 5-5m3-5c1-1 2-2 4-2h3m-4-4 4 4-4 4',shape:'M12 3c6-2 12 7 8 13-4 8-17 3-17-3 0-4 5-9 9-10Z',material:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M5 7c9-1 5 9 14 10M7 5c8 1 2 11 10 14',palette:'M12 3a9 9 0 0 0 0 18c3 0 3-3 2-4-2-2 0-4 2-3 7 1 5-11-4-11M7 10h.01M10 6h.01M15 6h.01',motion:'M3 8c4-9 8 14 12 5s5-6 6-4M3 16c4-9 8 7 12 3',background:'M3 3h18v18H3ZM3 16l6-7 5 6 3-3 4 4',lock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0v4',unlock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.shape}"/></svg>`;
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}icons();$('#undo').innerHTML=icon('undo');$('#redo').innerHTML=icon('redo');
let state=preset(0),activePreset=0,tab='shape',mode='rotate',phase=0,playing=false,dirty=true,ratio=1,renderer,history=[],future=[],dragBefore=null;
let randomAnchor=structuredClone(state),locks={},randomAmount=.45,randomScope='all',lastTick=0,lastDraw=0;
const canvas=$('#art'),board=$('#artboard');
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function remember(before=state){history.push(structuredClone(before));if(history.length>50)history.shift();future=[];historyButtons()}
function historyButtons(){$('#undo').disabled=!history.length;$('#redo').disabled=!future.length}historyButtons();
function mark(manual=true){dirty=true;if(manual){randomAnchor=structuredClone(state);$('#art-name').textContent='La tua esplorazione';activePreset=-1;$$('.preset').forEach(x=>x.classList.remove('active'))}syncHandles();syncTransport()}
function clampValue(key,value){const m=META[key];return m?Math.max(m[1],Math.min(m[2],Number(value))):value}
function setValue(key,value,record=false){if(record)remember();state[key]=clampValue(key,value);mark();syncValue(key)}
function format(key,v){return META[key]?.[3]>=1?Math.round(v):Number(v.toFixed(3))}
function slider(key,ends){const [label,min,max,step]=META[key],val=state[key];return `<div class="param"><div class="param-line"><label for="range-${key}">${label}</label><input class="number" aria-label="${label}: valore" data-number="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${format(key,val)}"></div><input id="range-${key}" data-param="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${val}" style="--fill:${(val-min)/(max-min)*100}%">${ends?`<div class="range-ends"><span>${ends[0]}</span><span>${ends[1]}</span></div>`:''}</div>`}
const section=(name,content)=>`<section class="control-section"><h2 class="section-title">${name}</h2>${content}</section>`;
const details=(name,content)=>`<details class="control-details"><summary>${name}</summary>${content}</details>`;
const colorField=(key,label)=>`<label class="color-field">${label}<input type="color" data-color="${key}" value="${state[key]}"></label>`;
const check=(key,label)=>`<label class="check"><input type="checkbox" data-check="${key}" ${state[key]?'checked':''}>${label}</label>`;
const TABLIST=[['shape','Forma','shape'],['material','Materia','material'],['color','Colori','palette'],['light','Luci','sun'],['motion','Moto','motion'],['background','Sfondo','background']];
function renderTabs(){$('#tabs').innerHTML=TABLIST.map(([id,name,ic])=>`<button class="tab ${tab===id?'active':''}" data-tab="${id}" aria-selected="${tab===id}">${icon(ic)}${name}</button>`).join('')}
function showTab(id){tab=id;renderTabs();renderControls();$('#controls').scrollTop=0}
function renderControls(){let html='';if(tab==='shape')html=section('GEOMETRIA',slider('volume',['Piatta','Volumetrica'])+slider('deform',['Regolare','Organica'])+slider('asymmetry')+slider('twist'))+section('CONTORNO',slider('edge',['Netto','Sfumato']))+details('Dimensioni e inquadratura',['stretchX','stretchY','stretchZ','scale','positionX','positionY','rotateX','rotateY'].map(k=>slider(k)).join(''))+details('Vuoto interno · anelli',['hole','holeX','holeY','holeShape'].map(k=>slider(k)).join(''))+details('Ritaglio · semilune',['cut','cutX','cutY'].map(k=>slider(k)).join(''))+details('Onde e increspature',slider('waves')+slider('waveScale'));
 if(tab==='material')html=`<p class="control-intro">Acqua, vetro, perla o metallo. Trova anche tutto quello che c’è nel mezzo.</p>`+section('SUPERFICIE',slider('metal',['Morbida','Metallica'])+slider('transparency',['Opaca','Trasparente'])+slider('roughness',['Levigata','Ruvida'])+slider('gloss'))+section('RIFLESSI E LUCE',slider('iridescence')+slider('emission'))+details('Dentro la materia',slider('refraction')+slider('thickness'));
 if(tab==='color')html=section('LA TUA PALETTE',`<div class="palette-colors">${state.palette.map((c,i)=>`<label class="color-swatch"><input type="color" data-palette="${i}" value="${c}" aria-label="Colore ${i+1} della palette"></label>`).join('')}</div><div class="mood-grid">${MOODS.map((m,i)=>`<button class="mood" data-mood="${i}"><span class="mood-dots">${m.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span>${m.name}</button>`).join('')}</div><button class="quiet full" id="random-palette">${icon('shuffle')}Palette casuale</button>`)+section('COME SI INCONTRANO I COLORI',slider('colorSoftness',['Bande nette','Sfumature'])+slider('gradientScale')+slider('gradientAngle')+slider('gradientOffset'))+section('FINITURA',slider('glow')+slider('grain'));
 if(tab==='light')html=`<p class="control-intro">Trascina i punti luminosi sulla tavola, oppure regola ogni sorgente qui.</p><button id="show-lights" class="quiet full">${icon('sun')}Mostra i comandi sulla tavola</button>`+section('LUCE PRINCIPALE',colorField('lightColor','Colore della luce')+['lightAngle','lightHeight','lightPower','lightSize'].map(k=>slider(k)).join(''))+section('SECONDA LUCE',check('light2','Attiva seconda luce')+colorField('light2Color','Colore della luce')+['light2Angle','light2Height','light2Power','light2Size'].map(k=>slider(k)).join(''));
 if(tab==='motion')html=`<p class="control-intro">Combina i movimenti. Ogni ciclo torna al punto di partenza.</p>`+section('COSA SI MUOVE',check('animateRotation','Rotazione completa')+check('animateShape','Forma e volume')+check('animateColor','Scorrimento dei colori')+check('animateLight','Orbita delle luci'))+section('RITMO',slider('motion',['Delicato','Ampio'])+slider('duration')+slider('speed',['Lento','Veloce']))+`<p class="help">Durata effettiva: <strong id="effective-duration">${(state.duration/state.speed).toFixed(1)} s</strong>. Usa il cursore sotto la tavola per esplorare ogni istante.</p>`;
 if(tab==='background')html=section('FONDO',`<label class="field">Tipo di sfondo<select id="bg-mode"><option value="solid" ${state.bgMode==='solid'?'selected':''}>Tinta unita</option><option value="gradient" ${state.bgMode==='gradient'?'selected':''}>Gradiente</option><option value="transparent" ${state.bgMode==='transparent'?'selected':''}>Trasparente</option></select></label>${colorField('background','Colore di sfondo')}${state.bgMode==='gradient'?colorField('background2','Secondo colore')+slider('bgAngle'):''}${state.bgMode==='transparent'?'<p class="help">La trasparenza viene conservata in PNG e WebP. Per JPEG e video viene usato il colore di sfondo scelto.</p>':''}`)+section('COMPOSIZIONE',slider('scale')+slider('positionX')+slider('positionY'));
 $('#controls').innerHTML=html;
}
function syncValue(key){const r=$(`[data-param="${key}"]`),n=$(`[data-number="${key}"]`);if(r){r.value=state[key];r.style.setProperty('--fill',`${(state[key]-META[key][1])/(META[key][2]-META[key][1])*100}%`)}if(n&&n!==document.activeElement)n.value=format(key,state[key])}
$('#tabs').addEventListener('click',e=>{const t=e.target.closest('[data-tab]');if(t)showTab(t.dataset.tab)});
$('#controls').addEventListener('pointerdown',e=>{if(e.target.matches('input'))dragBefore=structuredClone(state)});
$('#controls').addEventListener('focusin',e=>{if(e.target.matches('input')&&!dragBefore)dragBefore=structuredClone(state)});
$('#controls').addEventListener('input',e=>{const el=e.target;if(el.dataset.param){setValue(el.dataset.param,el.value)}if(el.dataset.number&&el.value!==''&&Number.isFinite(+el.value)){setValue(el.dataset.number,el.value)}if(el.dataset.palette!==undefined){state.palette[+el.dataset.palette]=el.value;mark()}if(el.dataset.color){state[el.dataset.color]=el.value;mark()}});
$('#controls').addEventListener('change',e=>{const el=e.target;if(el.matches('input')){remember(dragBefore||state);dragBefore=null}if(el.dataset.check){state[el.dataset.check]=el.checked;mark();if(el.dataset.check.startsWith('animate')&&el.checked)setPlaying(true)}if(el.id==='bg-mode'){remember();state.bgMode=el.value;mark();renderControls()}if(el.dataset.number){el.value=format(el.dataset.number,state[el.dataset.number])}});
$('#controls').addEventListener('click',e=>{const m=e.target.closest('[data-mood]');if(m){remember();state.palette=[...MOODS[+m.dataset.mood].colors];mark();renderControls();toast(`Palette ${MOODS[+m.dataset.mood].name}`)}if(e.target.closest('#random-palette')){remember();state.palette=[...MOODS[Math.floor(Math.random()*MOODS.length)].colors];mark();renderControls()}if(e.target.closest('#show-lights'))setMode('light')});
function applyPreset(i){remember();state=preset(i);activePreset=i;randomAnchor=structuredClone(state);phase=0;dirty=true;$('#art-name').textContent=PRESETS[i].name;$('#seed').value=state.seed;$$('.preset').forEach((p,j)=>p.classList.toggle('active',i===j));renderControls();syncTransport();syncHandles()}
function makePresets(){const thumb=document.createElement('canvas');let tr;try{tr=new Renderer(thumb)}catch{}$('#presets').innerHTML=PRESETS.map((p,i)=>{let url='';if(tr){tr.draw(preset(i),0,256,150);url=thumb.toDataURL()}return `<button class="preset ${i===0?'active':''}" data-preset="${i}" aria-label="Carica ${p.name}"><img class="preset-image" alt="" src="${url}"><span class="preset-name">${p.name}</span><span class="preset-sub">${p.label}</span></button>`}).join('');tr?.dispose()}
$('#presets').addEventListener('click',e=>{const p=e.target.closest('[data-preset]');if(p)applyPreset(+p.dataset.preset)});$('#reset').onclick=()=>applyPreset(0);
function undo(){if(!history.length)return;future.push(structuredClone(state));state=history.pop();mark(false);randomAnchor=structuredClone(state);renderControls();historyButtons();$('#seed').value=state.seed;$('#art-name').textContent='La tua esplorazione'}
function redo(){if(!future.length)return;history.push(structuredClone(state));state=future.pop();mark(false);randomAnchor=structuredClone(state);renderControls();historyButtons();$('#seed').value=state.seed}$('#undo').onclick=undo;$('#redo').onclick=redo;
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}if(e.code==='Space'){e.preventDefault();setPlaying(!playing)}});
function fitBoard(){const v=$('#viewport'),maxW=v.clientWidth,maxH=v.clientHeight;let w=maxW,h=w/ratio;if(h>maxH){h=maxH;w=h*ratio}board.style.width=`${Math.floor(w)}px`;board.style.height=`${Math.floor(h)}px`;dirty=true}
new ResizeObserver(fitBoard).observe($('#viewport'));$('#aspect').onchange=e=>{ratio=+e.target.value;fitBoard()};
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('#viewport').requestFullscreen)await $('#viewport').requestFullscreen();else toast('Usa la modalità a schermo intero del browser.')}catch{toast('Schermo intero non disponibile in questo browser.')}};
function setMode(m){mode=m;['rotate','move','light'].forEach(k=>$(`#${k}-tool`).classList.toggle('active',k===m));$('#light-handles').hidden=m!=='light';$('#gesture-hint').textContent={rotate:'Trascina per ruotare · scorri per ingrandire',move:'Trascina per spostare la figura',light:'Trascina i punti 1 e 2 per spostare le luci'}[m];syncHandles()}
['rotate','move','light'].forEach(m=>$(`#${m}-tool`).onclick=()=>setMode(m));$('#fit').onclick=()=>{remember();state.scale=1;state.positionX=0;state.positionY=0;state.rotateX=0;state.rotateY=0;mark();renderControls()};
function syncHandles(){for(let i=1;i<=2;i++){const prefix=i===1?'light':'light2',el=$(`#handle${i}`);el.style.left=`${(state[prefix+'Angle']/360+.5)*100}%`;el.style.top=`${(.5-state[prefix+'Height']/170)*100}%`;el.hidden=i===2&&!state.light2}}
let drag=null;const pointers=new Map();canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1){remember();drag={x:e.clientX,y:e.clientY,s:structuredClone(state)}}else if(pointers.size===2){const a=[...pointers.values()];drag.pinch=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);drag.baseScale=state.scale}});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!drag)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const a=[...pointers.values()];state.scale=clampValue('scale',drag.baseScale*Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)/drag.pinch)}else{const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(mode==='rotate'&&!e.shiftKey){state.rotateY=((drag.s.rotateY+dx*.45+540)%360)-180;state.rotateX=clampValue('rotateX',drag.s.rotateX+dy*.45)}else if(mode==='move'||e.shiftKey){const size=Math.min(board.clientWidth,board.clientHeight);state.positionX=clampValue('positionX',drag.s.positionX+dx/size*3.4);state.positionY=clampValue('positionY',drag.s.positionY-dy/size*3.4)}else{state.lightAngle=clampValue('lightAngle',drag.s.lightAngle+dx*.5);state.lightHeight=clampValue('lightHeight',drag.s.lightHeight-dy*.4)}}mark();['scale','rotateX','rotateY','positionX','positionY','lightAngle','lightHeight'].forEach(syncValue)});
function endDrag(e){pointers.delete(e.pointerId);if(!pointers.size)drag=null;else if(drag){const pt=[...pointers.values()][0];drag={x:pt.x,y:pt.y,s:structuredClone(state)}}}canvas.addEventListener('pointerup',endDrag);canvas.addEventListener('pointercancel',endDrag);
canvas.addEventListener('wheel',e=>{e.preventDefault();if(!canvas.wheelTimer)remember();clearTimeout(canvas.wheelTimer);canvas.wheelTimer=setTimeout(()=>canvas.wheelTimer=null,300);setValue('scale',state.scale-e.deltaY*.001)},{passive:false});
for(let i=1;i<=2;i++){const h=$(`#handle${i}`),prefix=i===1?'light':'light2';let moving=false;h.onpointerdown=e=>{e.stopPropagation();h.setPointerCapture(e.pointerId);moving=true;remember()};h.onpointermove=e=>{if(!moving)return;const b=board.getBoundingClientRect();state[prefix+'Angle']=clampValue(prefix+'Angle',((e.clientX-b.left)/b.width-.5)*360);state[prefix+'Height']=clampValue(prefix+'Height',(.5-(e.clientY-b.top)/b.height)*170);mark();syncValue(prefix+'Angle');syncValue(prefix+'Height')};h.onpointerup=h.onpointercancel=()=>moving=false;h.onkeydown=e=>{const k=e.key;if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(k))return;e.preventDefault();remember();const key=prefix+(['ArrowLeft','ArrowRight'].includes(k)?'Angle':'Height');setValue(key,state[key]+(k==='ArrowRight'||k==='ArrowUp'?5:-5))}}
function setPlaying(value){playing=value;lastTick=0;$('#play').innerHTML=icon(playing?'pause':'play');$('#play').setAttribute('aria-label',playing?'Metti in pausa':'Avvia animazione');$('#play-label').textContent=playing?'Movimento in corso':'Esplora il movimento'}
$('#play').onclick=()=>setPlaying(!playing);$('#motion-tab').onclick=()=>showTab('motion');$('#timeline').oninput=e=>{phase=+e.target.value/1000*Math.PI*2;dirty=true};
function syncTransport(){$('#loop-time').textContent=`${Number((state.duration/state.speed).toFixed(1))} s · LOOP`;if($('#effective-duration'))$('#effective-duration').textContent=`${(state.duration/state.speed).toFixed(1)} s`}
function frame(time){if(!lastTick)lastTick=time;const dt=Math.min((time-lastTick)/1000,.1);lastTick=time;if(playing&&!document.hidden){phase=(phase+dt*state.speed/state.duration*Math.PI*2)%(Math.PI*2);dirty=true;$('#timeline').value=phase/(Math.PI*2)*1000}if(renderer&&dirty&&time-lastDraw>33){const w=board.clientWidth,h=board.clientHeight,limit=window.innerWidth<700?620:820,scale=Math.min(devicePixelRatio||1,1.4,limit/Math.max(w,h));if(w&&h){renderer.draw(state,phase,Math.round(w*scale),Math.round(h*scale));$('#preview-size').textContent=`${Math.round(w*scale)} × ${Math.round(h*scale)}`;dirty=false;lastDraw=time}}requestAnimationFrame(frame)}
const groupNames={shape:'Forma',material:'Materia',color:'Colori',light:'Luci',background:'Sfondo'};
function renderLocks(){$('#lock-options').innerHTML=Object.entries(groupNames).map(([g,name])=>`<button class="lock ${locks[g]?'locked':''}" data-lock="${g}" aria-pressed="${!!locks[g]}">${icon(locks[g]?'lock':'unlock')}${name}</button>`).join('')}
$('#lock-options').onclick=e=>{const b=e.target.closest('[data-lock]');if(b){locks[b.dataset.lock]=!locks[b.dataset.lock];renderLocks()}};$('#random-settings').onclick=()=>{renderLocks();$('#random-dialog').showModal()};$('#variation').oninput=e=>{randomAmount=+e.target.value/100;$('#variation-value').textContent=`${e.target.value}%`};$('#random-scope').onchange=e=>randomScope=e.target.value;
function doRandom(){remember();let seed=Number($('#seed').value)>>>0;if(!$('#repeat-seed').checked)seed=crypto.getRandomValues(new Uint32Array(1))[0];const next=randomize(randomAnchor,seed,randomAmount,randomScope,{});for(const [g,keys] of Object.entries(GROUPS)){if(locks[g]||(randomScope!=='all'&&randomScope!==g))for(const k of keys)next[k]=structuredClone(state[k])}state=next;state.seed=seed;$('#seed').value=seed;mark(false);activePreset=-1;$$('.preset').forEach(p=>p.classList.remove('active'));$('#art-name').textContent='Esplorazione casuale';renderControls();toast('Una nuova possibilità')}
$('#seed').onchange=()=>{$('#repeat-seed').checked=true};$('#randomize').onclick=doRandom;$('#random-apply').onclick=()=>{doRandom();$('#random-dialog').close()};
// Exports use a separate render surface, preserving the preview and its exact framing.
let exportType='image',exportWidth=2048,exportHeight=2048,busy=false,cancelled=false,worker=null,exportRenderer=null;
const sizes=[['1024,1024','Quadrato · 1024 × 1024'],['2048,2048','Quadrato · 2048 × 2048'],['4096,4096','Quadrato · 4096 × 4096'],['1080,1920','Verticale · 1080 × 1920'],['2160,3840','Verticale 4K · 2160 × 3840'],['1920,1080','Desktop · 1920 × 1080'],['3840,2160','Desktop 4K · 3840 × 2160'],['custom','Personalizzata']];
function exportUI(){const selected=sizes.find(([v])=>v===`${exportWidth},${exportHeight}`)?.[0]||'custom';let html='';if(exportType==='image')html=`<label class="field">Formato del file<select id="file-format"><option value="png">PNG · qualità e trasparenza</option><option value="jpeg">JPEG · file leggero</option><option value="webp">WebP · qualità e file compatto</option></select></label>`;
 if(exportType==='video')html=`<label class="field">Destinazione<select id="video-target"><option value="desktop">Windows / Mac · video MP4</option><option value="iphone">iPhone · video per Live Photo</option></select></label>`;
 if(exportType!=='wallpaper'){html+=`<label class="field">Risoluzione<select id="export-resolution">${sizes.map(([v,n])=>`<option value="${v}" ${v===selected?'selected':''}>${n}</option>`).join('')}</select></label><div class="two-col"><label class="field">Larghezza<input id="export-width" type="number" min="64" max="4096" value="${exportWidth}"></label><label class="field">Altezza<input id="export-height" type="number" min="64" max="4096" value="${exportHeight}"></label></div><p class="export-meta" id="export-meta"></p>`}
 if(exportType==='image')html+='<p class="help">Il download conserva l’istante visibile e l’inquadratura della tavola. PNG e WebP supportano lo sfondo trasparente.</p>';
 if(exportType==='video')html+=`<div id="video-notes" class="export-note"><strong>MP4 H.264 · 30 fotogrammi/s · ciclo completo</strong><br>Windows: importa il video in Lively Wallpaper o Wallpaper Engine.<br>Mac: importa il video in un’app per wallpaper video, ad esempio Dynamic Wallpaper Engine.<br>I sistemi non impostano automaticamente il file come sfondo.</div><p class="help">Velocità e movimenti seguono il pannello Movimento. Tieni questa scheda aperta durante l’esportazione. Il video usa il colore di sfondo anche quando la tavola è trasparente.</p>`;
 if(exportType==='wallpaper')html=`<div class="export-note"><strong>Un wallpaper interattivo in un solo file HTML.</strong><br>Contiene la tua creazione e il suo movimento, funziona anche offline e si adatta allo schermo.</div><p class="help">Windows: importa il file in Lively Wallpaper.<br>Mac: aprilo con un’app per wallpaper web che supporti file locali.<br>Puoi anche aprirlo nel browser a schermo intero.</p>`;
 $('#export-options').innerHTML=html;$('#download-label').textContent={image:'Scarica immagine',video:'Crea e scarica MP4',wallpaper:'Scarica wallpaper HTML'}[exportType];$('#export-message').textContent='';exportMeta();
}
function exportMeta(){const el=$('#export-meta');if(el)el.textContent=`${exportWidth} × ${exportHeight} px${exportType==='video'?` · ${(state.duration/state.speed).toFixed(1)} s · 30 fps`:''}`}
function updateExportSize(w,h){exportWidth=w;exportHeight=h;ratio=w/h;const match=[...$('#aspect').options].find(o=>Math.abs(+o.value-ratio)<.001);$('#aspect').value=match?match.value:'';fitBoard();exportMeta()}
$('#export-open').onclick=()=>{const large=exportType==='image'?2048:1920;if(ratio>=1){exportWidth=large;exportHeight=Math.round(large/ratio)}else{exportHeight=large;exportWidth=Math.round(large*ratio)}exportUI();$('#export-dialog').showModal()};
$$('[data-export]').forEach(b=>b.onclick=()=>{if(busy)return;exportType=b.dataset.export;$$('[data-export]').forEach(x=>x.classList.toggle('selected',x===b));if(exportType==='video'&&Math.max(exportWidth,exportHeight)>1920){const factor=1920/Math.max(exportWidth,exportHeight);exportWidth=Math.round(exportWidth*factor/2)*2;exportHeight=Math.round(exportHeight*factor/2)*2}exportUI()});
